#!/bin/bash
# Bateria completa no formato SUPABASE: banco com auth/storage do Supabase (simulados), Agenda já existente
# com dados, migrações M00–M13 aplicadas por cima e o servidor local que imita as APIs do Supabase
# (Auth, PostgREST, Storage com RLS e Edge Functions em supabase/functions).
# Bateria completa (Etapas 1 a 8 + homologação). Cada bateria roda com todas as migrações (até a M10), salvo a Agenda isolada (M04). no ambiente local
cd "$(dirname "$0")"
[ -f chaves.json ] || { (node servidor.mjs >/dev/null 2>&1 &); sleep 2; pkill -f "node servidor[.]mjs"; }
SUPABASE_URL=http://localhost:8095 SUPABASE_ANON_KEY=$(node -p "require('./chaves.json').anon") node ../scripts/gerar-config.mjs >/dev/null
export SUPABASE_URL=$(node -p "require('./chaves.json').url") SUPABASE_ANON_KEY=$(node -p "require('./chaves.json').anon") SUPABASE_SERVICE_ROLE_KEY=$(node -p "require('./chaves.json').service")
reinicia(){ pkill -f "servidor/servidor.mjs"; pkill -f "node servidor[.]mjs"; for i in $(seq 1 40); do curl -s -o /dev/null http://localhost:8095/ || break; sleep 0.25; done; (node servidor.mjs > /tmp/srv.log 2>&1 &); for i in $(seq 1 40); do curl -sf -o /dev/null http://localhost:8095/ && break; sleep 0.25; done; }
echo "=== Migrações da Agenda (preservação e reversão) ==="; ./casos/teste-agenda-migracao.sh > /tmp/r-migracao.txt; tail -1 /tmp/r-migracao.txt
echo "=== Etapa 1: backend ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; node ./casos/teste-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-e1-backend.txt; tail -1 /tmp/r-e1-backend.txt
echo "=== Etapa 1: telas ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia
node ../scripts/criar-primeiros-masters.mjs "Primeiro Master Teste|master1@exemplo.com|31900000001" "Segundo Master Teste|master2@exemplo.com|31900000002" > /tmp/m.txt
node -e "const t=require('fs').readFileSync('/tmp/m.txt','utf8');const g=e=>t.match(new RegExp(e+'[^>]*> — senha temporária: (\\\\S+)'))[1];require('fs').writeFileSync('/tmp/masters.json',JSON.stringify({ezequiel:g('master1'),ronald:g('master2')}))"
timeout 300 node ./casos/teste-telas.mjs 2>&1 | grep -v Experimental > /tmp/r-e1-telas.txt; tail -1 /tmp/r-e1-telas.txt
for v in texto date; do echo "=== Etapa 2: Agenda backend (tipos $v) ==="; ./reset.sh 4 $v >/dev/null; reinicia; node ./casos/teste-agenda-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-e2-backend-$v.txt; tail -1 /tmp/r-e2-backend-$v.txt; done
echo "=== Etapa 2: Agenda original × integrada (telas) ==="; timeout 600 node ./casos/teste-agenda-telas.mjs 2>&1 | grep -v Experimental > /tmp/r-e2-telas.txt; tail -1 /tmp/r-e2-telas.txt
echo "=== Etapa 2: Agenda backend com todas as migrações (M10) ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; node ./casos/teste-agenda-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-e2-backend-m09.txt; tail -1 /tmp/r-e2-backend-m09.txt
echo "=== Etapa 3: Cursos backend ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; node ./casos/teste-cursos-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-e3-backend.txt; tail -1 /tmp/r-e3-backend.txt
echo "=== Etapa 3: Cursos telas ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 300 node ./casos/teste-cursos-telas.mjs 2>&1 | grep -v Experimental > /tmp/r-e3-telas.txt; tail -1 /tmp/r-e3-telas.txt
echo "=== Etapa 4: Secretaria e Tesouraria backend ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; node ./casos/teste-financeiro-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-e4-backend.txt; tail -1 /tmp/r-e4-backend.txt
echo "=== Etapa 4: Secretaria e Tesouraria telas ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 400 node ./casos/teste-financeiro-telas.mjs 2>&1 | grep -v Experimental > /tmp/r-e4-telas.txt; tail -1 /tmp/r-e4-telas.txt
echo "=== Etapa 5: Membros, voluntários e termos backend ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; node ./casos/teste-membros-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-e5-backend.txt; tail -1 /tmp/r-e5-backend.txt
echo "=== Etapa 5: Membros, voluntários e termos telas ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 400 node ./casos/teste-membros-telas.mjs 2>&1 | grep -v Experimental > /tmp/r-e5-telas.txt; tail -1 /tmp/r-e5-telas.txt
echo "=== Etapa 6: Certificados e cerimônias backend ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; node ./casos/teste-certificados-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-e6-backend.txt; tail -1 /tmp/r-e6-backend.txt
echo "=== Etapa 6: Certificados e cerimônias telas ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 400 node ./casos/teste-certificados-telas.mjs 2>&1 | grep -v Experimental > /tmp/r-e6-telas.txt; tail -1 /tmp/r-e6-telas.txt
echo "=== Etapa 7: Mídia e escalas backend ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; node ./casos/teste-escalas-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-e7-backend.txt; tail -1 /tmp/r-e7-backend.txt
echo "=== Etapa 7: Mídia e escalas telas ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 400 node ./casos/teste-escalas-telas.mjs 2>&1 | grep -v Experimental > /tmp/r-e7-telas.txt; tail -1 /tmp/r-e7-telas.txt
echo "=== Etapa 7: escalas com Agenda em tipos date ==="; ./reset.sh 13 date >/dev/null; rm -rf _storage; reinicia; node ./casos/teste-escalas-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-e7-backend-date.txt; tail -1 /tmp/r-e7-backend-date.txt
echo "=== Etapa 8: identidade visual (todas as telas) ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 500 node ./casos/teste-identidade.mjs 2>&1 | grep -v Experimental > /tmp/r-e8-identidade.txt; tail -1 /tmp/r-e8-identidade.txt
echo "=== Homologação: segurança (tabelas, funções, Edge Functions, limites, XSS) ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 500 node ./casos/teste-seguranca.mjs 2>&1 | grep -v Experimental > /tmp/r-h-seguranca.txt; tail -1 /tmp/r-h-seguranca.txt
echo "=== Homologação: conta sem perfil ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; node ./casos/teste-conta-sem-perfil.mjs 2>&1 | grep -v Experimental > /tmp/r-h-semperfil.txt; tail -1 /tmp/r-h-semperfil.txt
echo "=== Interface e acesso: rodapé, senha, Ir para, menu do usuário, Meu perfil, Sair ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 500 node ./casos/teste-perfil-menu.mjs 2>&1 | grep -v Experimental > /tmp/r-perfil-menu.txt; tail -1 /tmp/r-perfil-menu.txt
echo "=== M12: ministérios, organogramas, fotos, contatos, Colégio e link privado da Agenda (backend) ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 300 node ./casos/teste-institucional-backend.mjs 2>&1 | grep -v Experimental > /tmp/r-m12-backend.txt; tail -1 /tmp/r-m12-backend.txt
echo "=== M12: telas (site público, Área de Membros e formulário no celular) ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; timeout 500 node ./casos/teste-institucional-telas.mjs 2>&1 | grep -v Experimental > /tmp/r-m12-telas.txt; tail -1 /tmp/r-m12-telas.txt
echo "=== M12: desfazer e refazer (com dados) ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; P="psql -h /tmp -p 5434 -U postgres -d betel -v ON_ERROR_STOP=1 -q"; ($P -f ../supabase/rollback/20261121001200_m12_institucional.down.sql && $P -f ../supabase/migrations/20261121001200_m12_institucional.sql) >/tmp/r-m12-rev.log 2>&1 && echo "Resultado: reversão ok" || { echo "  ✗ reversão da M12 falhou"; tail -5 /tmp/r-m12-rev.log; }
echo "=== M13: desfazer e refazer ==="; ./reset.sh 13 texto >/dev/null; P="psql -h /tmp -p 5434 -U postgres -d betel -v ON_ERROR_STOP=1 -q"; ($P -f ../supabase/rollback/20261121001300_m13_tarefas_agendadas.down.sql && $P -f ../supabase/migrations/20261121001300_m13_tarefas_agendadas.sql) >/dev/null 2>&1 && echo "Resultado: reversão ok" || echo "  ✗ reversão da M13 falhou"
echo "=== M11: desfazer e refazer ==="; ./reset.sh 11 texto >/dev/null; P="psql -h /tmp -p 5434 -U postgres -d betel -v ON_ERROR_STOP=1 -q"; ($P -f ../supabase/rollback/20261121001100_m11_meu_perfil.down.sql && $P -f ../supabase/migrations/20261121001100_m11_meu_perfil.sql) >/dev/null 2>&1 && echo "Resultado: reversão ok" || echo "  ✗ reversão da M11 falhou"
echo "=== M10: desfazer e refazer ==="; ./reset.sh 10 texto >/dev/null; P="psql -h /tmp -p 5434 -U postgres -d betel -v ON_ERROR_STOP=1 -q"; ($P -f ../supabase/rollback/20261121001000_m10_homologacao_reforcos.down.sql && $P -f ../supabase/migrations/20261121001000_m10_homologacao_reforcos.sql) >/dev/null 2>&1 && echo "Resultado: reversão ok" || echo "  ✗ reversão da M10 falhou"
echo "=== M09: desfazer e refazer ==="; ./reset.sh 9 texto >/dev/null; P="psql -h /tmp -p 5434 -U postgres -d betel -v ON_ERROR_STOP=1 -q"; ($P -f ../supabase/rollback/20261121000900_m09_midia_escalas.down.sql && $P -f ../supabase/migrations/20261121000900_m09_midia_escalas.sql) >/dev/null 2>&1 && echo "Resultado: reversão ok" || echo "  ✗ reversão da M09 falhou"
echo "=== M08: desfazer e refazer ==="; ./reset.sh 8 texto >/dev/null; P="psql -h /tmp -p 5434 -U postgres -d betel -v ON_ERROR_STOP=1 -q"; ($P -f ../supabase/rollback/20261121000800_m08_certificados_cerimonias.down.sql && $P -f ../supabase/migrations/20261121000800_m08_certificados_cerimonias.sql) >/dev/null 2>&1 && echo "Resultado: reversão ok" || echo "  ✗ reversão da M08 falhou"
echo "=== M07: desfazer e refazer ==="; ./reset.sh 7 texto >/dev/null; P="psql -h /tmp -p 5434 -U postgres -d betel -v ON_ERROR_STOP=1 -q"; ($P -f ../supabase/rollback/20261121000700_m07_membros_voluntarios_termos.down.sql && $P -f ../supabase/migrations/20261121000700_m07_membros_voluntarios_termos.sql) >/dev/null 2>&1 && echo "Resultado: reversão ok" || echo "  ✗ reversão da M07 falhou"
grep -h "✗" /tmp/r-*.txt
echo "=== Fumaça: site estático (como no Render) + API do Supabase em outra origem ==="; ./reset.sh 13 texto >/dev/null; rm -rf _storage; reinicia; (PORT=8080 node ../scripts/servir-local.mjs > /tmp/estatico.log 2>&1 &); sleep 1; SITE=http://localhost:8080 timeout 300 node casos/fumaca-estatico.mjs 2>&1 | grep -v Experimental > /tmp/r-fumaca.txt; tail -1 /tmp/r-fumaca.txt; pkill -f servir-local.mjs
